function compute(x) {
  const n = Math.round(x.n);
  let probs = [x.p1, x.p2, x.p3, x.p4].slice(0, n);
  let sum = probs.reduce((a, b) => a + b, 0);
  if (sum === 0) {
    probs = probs.map(() => 1 / n);
  } else {
    probs = probs.map(p => p / sum);
  }
  const contributions = probs.map(p => {
    if (p === 0) return 0;
    return -p * Math.log2(p);
  });
  const H = contributions.reduce((a, b) => a + b, 0);
  const insight = `With n=${n}, the entropy is ${H.toFixed(3)} bits.`;
  return {
    H: { type: 'scalar', value: H, label: 'Entropy (bits)' },
    probs: { type: 'vector', value: probs, labels: probs.map((_, i) => `p${i+1}`) },
    contributions: { type: 'vector', value: contributions, labels: contributions.map((_, i) => `-p${i+1} log2 p${i+1}`) },
    insight: insight
  };
}
